CREATE TEMP TABLE catalogue_input ON COMMIT DROP AS SELECT * FROM jsonb_to_recordset('[{"id":"baa939cc-37f6-5de5-827f-c7f643cf3701","source_id":"0173","name_en":"cable incline triceps extension","name_ar":"\u062a\u0645\u062f\u064a\u062f \u0643\u0627\u0628\u0644 \u0627\u0646\u062d\u062f\u0631 \u062b\u0644\u0627\u062b\u064a\u0629 \u0627\u0644\u0631\u0624\u0648\u0633","match_names":["cable incline triceps extension"],"muscle":"triceps","equipment":"cable","aliases":["cable incline triceps extension"],"logging_mode":"weighted_reps","load_convention":"external_total","guidance":{"steps_en":"Adjust the cable machine to a low pulley position.\nAttach a straight bar to the cable.\nStand facing away from the machine with your feet shoulder-width apart.\nGrasp the bar with an overhand grip and extend your arms straight overhead.\nLean forward slightly, keeping your back straight and core engaged.\nBend your elbows and lower the bar behind your head, keeping your upper arms close to your ears.\nPause for a moment, then extend your arms back to the starting position.\nRepeat for the desired number of repetitions.","steps_ar":"\u0627\u0636\u0628\u0637 \u0622\u0644\u0629 \u0627\u0644\u0643\u0627\u0628\u0644 \u0639\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u0643\u0631\u0629 \u0627\u0644\u0645\u0646\u062e\u0641\u0636.\n\u0642\u0645 \u0628\u062a\u0648\u0635\u064a\u0644 \u0634\u0631\u064a\u0637 \u0645\u0633\u062a\u0642\u064a\u0645 \u0628\u0627\u0644\u0643\u0627\u0628\u0644.\n\u0642\u0641 \u0628\u0639\u064a\u062f\u064b\u0627 \u0639\u0646 \u0627\u0644\u0645\u0627\u0643\u064a\u0646\u0629 \u0645\u0639 \u0645\u0628\u0627\u0639\u062f\u0629 \u0642\u062f\u0645\u064a\u0643 \u0628\u0645\u0642\u062f\u0627\u0631 \u0639\u0631\u0636 \u0627\u0644\u0643\u062a\u0641\u064a\u0646.\n\u0623\u0645\u0633\u0643 \u0627\u0644\u0634\u0631\u064a\u0637 \u0628\u0642\u0628\u0636\u0629 \u064a\u062f \u0648\u0645\u062f \u0630\u0631\u0627\u0639\u064a\u0643 \u0628\u0634\u0643\u0644 \u0645\u0633\u062a\u0642\u064a\u0645 \u0625\u0644\u0649 \u0627\u0644\u0623\u0639\u0644\u0649.\n\u0627\u0646\u062d\u0646\u0650 \u0625\u0644\u0649 \u0627\u0644\u0623\u0645\u0627\u0645 \u0642\u0644\u064a\u0644\u064b\u0627\u060c \u0645\u0639 \u0627\u0644\u062d\u0641\u0627\u0638 \u0639\u0644\u0649 \u0627\u0633\u062a\u0642\u0627\u0645\u0629 \u0638\u0647\u0631\u0643 \u0648\u0646\u0634\u0627\u0637\u0643 \u0627\u0644\u0623\u0633\u0627\u0633\u064a.\n\u0642\u0645 \u0628\u062b\u0646\u064a \u0645\u0631\u0641\u0642\u064a\u0643 \u0648\u062e\u0641\u0636 \u0627\u0644\u0628\u0627\u0631 \u062e\u0644\u0641 \u0631\u0623\u0633\u0643\u060c \u0645\u0639 \u0625\u0628\u0642\u0627\u0621 \u0630\u0631\u0627\u0639\u064a\u0643 \u0627\u0644\u0639\u0644\u0648\u064a\u062a\u064a\u0646 \u0628\u0627\u0644\u0642\u0631\u0628 \u0645\u0646 \u0623\u0630\u0646\u064a\u0643.\n\u062a\u0648\u0642\u0641 \u0644\u0644\u062d\u0638\u0629\u060c \u062b\u0645 \u0642\u0645 \u0628\u0645\u062f \u0630\u0631\u0627\u0639\u064a\u0643 \u0645\u0631\u0629 \u0623\u062e\u0631\u0649 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"0173","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"triceps","secondary_muscles":["shoulders"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/0173-Hx1WC8I.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/0173-Hx1WC8I.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"a40fbe05-0500-52ba-87bb-fadf5831c094","source_id":"0174","name_en":"cable judo flip","name_ar":"\u0642\u0644\u0628 \u0627\u0644\u062c\u0648\u062f\u0648 \u0628\u0627\u0644\u0643\u0627\u0628\u0644","match_names":["cable judo flip"],"muscle":"core","equipment":"cable","aliases":["cable judo flip"],"logging_mode":"weighted_reps","load_convention":"external_total","guidance":{"steps_en":"Stand facing the cable machine with your feet shoulder-width apart.\nHold the cable handle with both hands at chest level, palms facing down.\nEngage your core and rotate your torso to the right, pulling the cable across your body.\nAs you rotate, pivot your back foot and allow your hips to rotate naturally.\nExtend your arms fully and finish the movement by flipping the cable handle over your shoulder.\nReturn to the starting position by reversing the movement, rotating your torso back to the center.\nRepeat the movement on the opposite side.\nContinue alternating sides for the desired number of repetitions.","steps_ar":"\u0642\u0641 \u0641\u064a \u0645\u0648\u0627\u062c\u0647\u0629 \u062c\u0647\u0627\u0632 \u0627\u0644\u0643\u0627\u0628\u0644 \u0645\u0639 \u0645\u0628\u0627\u0639\u062f\u0629 \u0642\u062f\u0645\u064a\u0643 \u0628\u0645\u0642\u062f\u0627\u0631 \u0639\u0631\u0636 \u0627\u0644\u0643\u062a\u0641\u064a\u0646.\n\u0623\u0645\u0633\u0643 \u0645\u0642\u0628\u0636 \u0627\u0644\u0643\u0627\u0628\u0644 \u0628\u0643\u0644\u062a\u0627 \u064a\u062f\u064a\u0643 \u0639\u0644\u0649 \u0645\u0633\u062a\u0648\u0649 \u0627\u0644\u0635\u062f\u0631\u060c \u0645\u0639 \u062a\u0648\u062c\u064a\u0647 \u0631\u0627\u062d\u062a\u064a \u0627\u0644\u064a\u062f\u064a\u0646 \u0644\u0644\u0623\u0633\u0641\u0644.\n\u0642\u0645 \u0628\u0625\u0634\u0631\u0627\u0643 \u0642\u0644\u0628\u0643 \u0648\u0642\u0645 \u0628\u062a\u062f\u0648\u064a\u0631 \u062c\u0630\u0639\u0643 \u0625\u0644\u0649 \u0627\u0644\u064a\u0645\u064a\u0646\u060c \u0648\u0633\u062d\u0628 \u0627\u0644\u0643\u0627\u0628\u0644 \u0639\u0628\u0631 \u062c\u0633\u0645\u0643.\n\u0623\u062b\u0646\u0627\u0621 \u0627\u0644\u062a\u062f\u0648\u064a\u0631\u060c \u0642\u0645 \u0628\u062a\u062f\u0648\u064a\u0631 \u0642\u062f\u0645\u0643 \u0627\u0644\u062e\u0644\u0641\u064a\u0629 \u0648\u0627\u0633\u0645\u062d \u0644\u0644\u0648\u0631\u0643\u064a\u0646 \u0628\u0627\u0644\u062f\u0648\u0631\u0627\u0646 \u0628\u0634\u0643\u0644 \u0637\u0628\u064a\u0639\u064a.\n\u0645\u062f \u0630\u0631\u0627\u0639\u064a\u0643 \u0628\u0627\u0644\u0643\u0627\u0645\u0644 \u0648\u0623\u0643\u0645\u0644 \u0627\u0644\u062d\u0631\u0643\u0629 \u0639\u0646 \u0637\u0631\u064a\u0642 \u0642\u0644\u0628 \u0645\u0642\u0628\u0636 \u0627\u0644\u0643\u0627\u0628\u0644 \u0641\u0648\u0642 \u0643\u062a\u0641\u0643.\n\u0627\u0631\u062c\u0639 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629 \u0639\u0646 \u0637\u0631\u064a\u0642 \u0639\u0643\u0633 \u0627\u0644\u062d\u0631\u0643\u0629\u060c \u0648\u062a\u062f\u0648\u064a\u0631 \u062c\u0630\u0639\u0643 \u0645\u0631\u0629 \u0623\u062e\u0631\u0649 \u0625\u0644\u0649 \u0627\u0644\u0645\u0631\u0643\u0632.\n\u0643\u0631\u0631 \u0627\u0644\u062d\u0631\u0643\u0629 \u0639\u0644\u0649 \u0627\u0644\u062c\u0627\u0646\u0628 \u0627\u0644\u0622\u062e\u0631.\n\u0627\u0633\u062a\u0645\u0631 \u0628\u0627\u0644\u062a\u0646\u0627\u0648\u0628 \u0628\u064a\u0646 \u0627\u0644\u062c\u0627\u0646\u0628\u064a\u0646 \u0644\u0644\u062d\u0635\u0648\u0644 \u0639\u0644\u0649 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631\u0627\u062a.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"0174","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_dra