2a\u0631\u0627\u062c\u0639 \u0625\u0644\u0649 \u0627\u0644\u062e\u0644\u0641 \u0644\u062e\u0644\u0642 \u062a\u0648\u062a\u0631 \u0641\u064a \u0627\u0644\u0643\u0627\u0628\u0644.\n\u0627\u062b\u0646\u0650 \u0631\u0643\u0628\u062a\u064a\u0643 \u0642\u0644\u064a\u0644\u064b\u0627 \u0648\u062b\u0628\u062a\u0647\u0645\u0627 \u0644\u0644\u0623\u0645\u0627\u0645 \u0639\u0646\u062f \u0627\u0644\u0648\u0631\u0643\u064a\u0646\u060c \u0645\u0639 \u0627\u0644\u062d\u0641\u0627\u0638 \u0639\u0644\u0649 \u0627\u0633\u062a\u0642\u0627\u0645\u0629 \u0638\u0647\u0631\u0643.\n\u0623\u0628\u0642\u0650 \u0630\u0631\u0627\u0639\u0643 \u0627\u0644\u0639\u0644\u0648\u064a \u0642\u0631\u064a\u0628\u064b\u0627 \u0645\u0646 \u062c\u0633\u0645\u0643 \u0648\u062b\u0646\u064a \u0645\u0631\u0641\u0642\u0643 \u0628\u0632\u0627\u0648\u064a\u0629 90 \u062f\u0631\u062c\u0629.\n\u0642\u0645 \u0628\u0645\u062f \u0633\u0627\u0639\u062f\u0643 \u0625\u0644\u0649 \u0627\u0644\u062e\u0644\u0641\u060c \u0645\u0639 \u0641\u0631\u062f \u0630\u0631\u0627\u0639\u0643 \u0628\u0627\u0644\u0643\u0627\u0645\u0644.\n\u062a\u0648\u0642\u0641 \u0644\u0644\u062d\u0638\u0629\u060c \u062b\u0645 \u0639\u062f \u0628\u0628\u0637\u0621 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0630\u0644\u0643 \u0628\u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631\u0627\u062a\u060c \u062b\u0645 \u0628\u062f\u0644 \u0627\u0644\u062c\u0648\u0627\u0646\u0628.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"0860","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"triceps","secondary_muscles":["shoulders"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/0860-HEJ6DIX.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/0860-HEJ6DIX.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"992d6d76-35f8-5540-8d28-9051b827661a","source_id":"0175","name_en":"cable kneeling crunch","name_ar":"\u0623\u0632\u0645\u0629 \u0631\u0643\u0648\u0639 \u0627\u0644\u0643\u0627\u0628\u0644","match_names":["cable kneeling crunch"],"muscle":"core","equipment":"cable","aliases":["cable kneeling crunch"],"logging_mode":"weighted_reps","load_convention":"external_total","guidance":{"steps_en":"Attach a rope handle to a high pulley and kneel down facing away from the machine.\nHold the rope handle with both hands and place it behind your head, keeping your elbows out to the sides.\nKeeping your hips stationary, flex your waist and crunch your torso down towards your thighs.\nPause for a moment at the bottom, then slowly return to the starting position.\nRepeat for the desired number of repetitions.","steps_ar":"\u0642\u0645 \u0628\u062a\u0648\u0635\u064a\u0644 \u0645\u0642\u0628\u0636 \u062d\u0628\u0644 \u0628\u0628\u0643\u0631\u0629 \u0639\u0627\u0644\u064a\u0629 \u062b\u0645 \u0627\u0631\u0643\u0639 \u0644\u0623\u0633\u0641\u0644 \u0648\u0648\u062c\u0647\u0643 \u0628\u0639\u064a\u062f\u064b\u0627 \u0639\u0646 \u0627\u0644\u0645\u0627\u0643\u064a\u0646\u0629.\n\u0623\u0645\u0633\u0643 \u0645\u0642\u0628\u0636 \u0627\u0644\u062d\u0628\u0644 \u0628\u0643\u0644\u062a\u0627 \u064a\u062f\u064a\u0643 \u0648\u0636\u0639\u0647 \u062e\u0644\u0641 \u0631\u0623\u0633\u0643\u060c \u0645\u0639 \u0625\u0628\u0642\u0627\u0621 \u0645\u0631\u0641\u0642\u064a\u0643 \u0645\u0641\u062a\u0648\u062d\u064a\u0646 \u0639\u0644\u0649 \u0627\u0644\u062c\u0627\u0646\u0628\u064a\u0646.\n\u0623\u0628\u0642\u0650 \u0648\u0631\u0643\u064a\u0643 \u062b\u0627\u0628\u062a\u064a\u0646\u060c \u0648\u0642\u0645 \u0628\u062b\u0646\u064a \u062e\u0635\u0631\u0643 \u0648\u0627\u0636\u063a\u0637 \u062c\u0630\u0639\u0643 \u0644\u0623\u0633\u0641\u0644 \u0628\u0627\u062a\u062c\u0627\u0647 \u0641\u062e\u0630\u064a\u0643.\n\u062a\u0648\u0642\u0641 \u0644\u0644\u062d\u0638\u0629 \u0641\u064a \u0627\u0644\u0623\u0633\u0641\u0644\u060c \u062b\u0645 \u0639\u062f \u0628\u0628\u0637\u0621 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"0175","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"abs","secondary_muscles":["obliques"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/0175-WW95auq.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/0175-WW95auq.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"14b31ecc-8130-52b3-8233-1a43ac9c4bc9","source_id":"3697","name_en":"cable kneeling rear delt row (with rope) (male)","name_ar":"\u0643\u0627\u0628\u0644 \u0631\u0627\u0643\u0639 \u0627\u0644\u0635\u0641 \u0627\u0644\u062e\u0644\u0641\u064a (\u0645\u0639 \u062d\u0628\u0644) (\u0630\u0643\u0631)","match_names":["cable kneeling rear delt row (with rope) (male)"],"muscle":"shoulders","equipment":"cable","aliases":["cable kneeling rear delt row (with rope) (male)"],"logging_mode":"weighted_reps","load_convention":"external_total","guidance":{"steps_en":"Attach a rope handle to a low cable pulley and kneel down facing the machine.\nGrasp the rope with a neutral grip (palms facing each other) and extend your arms fully in front of you.\nKeeping your back straight and core engaged, pull the rope towards your body by retracting your shoulder blades.\nSqueeze your shoulder blades together at the end of the movement and hold for a brief pause.\nSlowly release the tension and return to the starting position.\nRepeat for the desired number of repetitions.","steps_ar":"\u0642\u0645 \u0628\u062a\u0648\u0635\u064a\u0644 \u0645\u0642\u0628\u0636 \u062d\u0628\u0644 \u0628\u0628\u0643\u0631\u0629 \u0643\u0627\u0628\u0644 \u0645\u0646\u062e\u0641\u0636\u0629 \u0648\u0627\u0631\u0643\u0639 \u0641\u064a \u0645\u0648\u0627\u062c\u0647\u0629 \u0627\u0644\u0645\u0627\u0643\u064a\u0646\u0629.\n\u0623\u0645\u0633\u0643 \u0627\u0644\u062d\u0628\u0644 \u0628\u0642\u0628\u0636\u0629 \u0645\u062d\u0627\u064a\u062f\u0629 (\u0643\u0641 \u0627\u0644\u064a\u062f \u0641\u064a \u0645\u0648\u0627\u062c\u0647\u0629 \u0628\u0639\u0636\u0647\u0627 \u0627\u0644\u0628\u0639\u0636) \u0648\u0645\u062f \u0630\u0631\u0627\u0639\u064a\u0643 \u0628\u0627\u0644\u0643\u0627\u0645\u0644 \u0623\u0645\u0627\u0645\u0643.\n\u062d\u0627\u0641\u0638 \u0639\u0644\u0649 \u0627\u0633\u062a\u0642\u0627\u0645\u0629 \u0638\u0647\u0631\u0643 \u0648\u0634\u062f \u0627\u0644\u062c\u0630\u0639\u060c \u0648\u0627\u0633\u062d\u0628 \u0627\u0644\u062d\u0628\u0644 \u0646\u062d\u0648 \u062c\u0633\u0645\u0643 \u0639\u0646 \u0637\u0631\u064a\u0642 \u0633\u062d\u0628 \u0644\u0648\u062d\u064a \u0643\u062a\u0641\u0643.\n\u0627\u0636\u063a\u0637 \u0639\u0644\u0649 \u0644\u0648\u062d\u064a \u0643\u062a\u0641\u0643 \u0645\u0639\u064b\u0627 \u0641\u064a \u0646\u0647\u0627\u064a\u0629 \u0627\u0644\u062d\u0631\u0643\u0629 \u0648\u0627\u0633\u062a\u0645\u0631 \u0641\u064a \u0627\u0644\u062a\u0648\u0642\u0641 \u0644\u0641\u062a\u0631\u0629 \u0642\u0635\u064a\u0631\u0629.\n\u062d\u0631\u0631 \u0627\u0644\u062a\u0648\u062a\u0631 \u0628\u0628\u0637\u0621 \u062b\u0645 \u0639\u062f \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"3697","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"delts","secondary_muscles":["trapezius","rhomboids","biceps"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/3697-G61cXLk.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/3697-G61cXLk.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"4958e04e-fa20-5e47-87d5-b05902647f0a","source_id":"0176","name_en":"cable kneeling triceps extension","name_ar":"\u062a\u0645\u062f\u064a\u062f \u0643\u0627\u0628\u0644 \u0627\u0644\u0631\u0643\u0648\u0639 \u062b\u0644\u0627\u062b\u064a\u0629 \u0627\u0644\u0631\u0624\u0648\u0633","match_names":["cable kneeling triceps extension"],"muscle":"triceps","equipment":"cable","aliases":["cable kneeling triceps extension"],"logging_mode":"weighted_reps","load_convention":"external_total","guidance":{"steps_en":"Attach a rope handle to a high pulley and kneel down facing the cable machine.\nGrasp the rope with a neutral grip (palms facing each other) and bring your hands to the sides of your head.\nKeep your elbows close to your head and your upper arms stationary throughout the exercise.\nExtend your forearms by contracting your triceps until your arms are fully extended.\nPause for a moment, then slowly return to the starting position by bending your elbows.\nRepeat for the desired number of repetitions.","steps_ar":"\u0627\u0631\u0628\u0637 \u0645\u0642\u0628\u0636 \u062d\u0628\u0644 \u0628\u0628\u0643\u0631\u0629 \u0639\u0627\u0644\u064a\u0629 \u0648\u0627\u0631\u0643\u0639 \u0641\u064a \u0645\u0648\u0627\u062c\u0647\u0629 \u0622\u0644\u0629 \u0627\u0644\u0643\u0627\u0628\u0644.\n\u0623\u0645\u0633\u0643 \u0627\u0644\u062d\u0628\u0644 \u0628\u0642\u0628\u0636\u0629 \u0645\u062d\u0627\u064a\u062f\u0629 (\u0643\u0641 \u0627\u0644\u064a\u062f \u062a\u0648\u0627\u062c\u0647 \u0628\u0639\u0636\u0647\u0627 \u0627\u0644\u0628\u0639\u0636) \u0648\u0627\u0631\u0641\u0639 \u064a\u062f\u064a\u0643 \u0625\u0644\u0649 \u062c\u0627\u0646\u0628\u064a \u0631\u0623\u0633\u0643.\n\u0623\u0628\u0642\u0650 \u0645\u0631\u0641\u0642\u064a\u0643 \u0642\u0631\u064a\u0628\u064a\u0646 \u0645\u0646 \u0631\u0623\u0633\u0643 \u0648\u0630\u0631\u0627\u0639\u064a\u0643 \u0627\u0644\u0639\u0644\u0648\u064a\u064a\u0646 \u062b\u0627\u0628\u062a\u064a\u0646 \u0637\u0648\u0627\u0644 \u0627\u0644\u062a\u0645\u0631\u064a\u0646.\n\u0642\u0645 \u0628\u062a\u0645\u062f\u064a\u062f \u0633\u0627\u0639\u062f\u064a\u0643 \u0639\u0646 \u0637\u0631\u064a\u0642 \u062a\u0642\u0644\u064a\u0635 \u0627\u0644\u0639\u0636\u0644\u0629 \u062b\u0644\u0627\u062b\u064a\u0629 \u0627\u0644\u0631\u0624\u0648\u0633 \u062d\u062a\u0649 \u064a\u062a\u0645 \u062a\u0645\u062f\u064a\u062f \u0630\u0631\u0627\u0639\u064a\u0643 \u0628\u0627\u0644\u0643\u0627\u0645\u0644.\n\u062a\u0648\u0642\u0641 \u0644\u0644\u062d\u0638\u0629\u060c \u062b\u0645 \u0639\u062f \u0628\u0628\u0637\u0621 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629 \u0639\u0646 \u0637\u0631\u064a\u0642 \u062b\u0646\u064a \u0645\u0631\u0641\u0642\u064a\u0643.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"0176","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"triceps","secondary_muscles":["shoulders"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/0176-KWdF2JI.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/0176-KWdF2JI.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"9949981e-fc2e-5acc-8c69-8bcd53db97ef","source_id":"2330","name_en":"cable lat pulldown full range of motion","name_ar":"\u0643\u0627\u0628\u0644 \u0627\u0644\u0644\u0627\u062a \u0627\u0644\u0645\u0646\u0633\u062f\u0644\u0629 \u0645\u062c\u0645\u0648\u0639\u0629 \u0643\u0627\u0645\u0644\u0629 \u0645\u0646 \u0627\u0644\u062d\u0631\u0643\u0629","match_names":["cable lat pulldown full range of motion"],"muscle":"back","equipment":"cable","aliases":["cable lat pulldown full range of motion"],"logging_mode":"weighted_reps","load_convention":"external_total","guidance":{"steps_en":"Sit on the lat pulldown machine with your knees positioned under the pads.\nGrasp the cable bar with an overhand grip, slightly wider than shoulder-width apart.\nLean back slightly and keep your chest up, maintaining a slight arch in your lower back.\nPull the bar down towards your upper chest, squeezing your shoulder blades together.\nPause for a moment at the bottom of the movement, then slowly release the bar back to the starting position.\nRepeat for the desired number of repetitions.","steps_ar":"\u0627\u062c\u0644\u0633 \u0639\u0644\u0649 \u0622\u0644\u0629 \u0627\u0644\u0633\u062d\u0628 \u0644\u0623\u0633\u0641\u0644 \u0645\u0639 \u0648\u0636\u0639 \u0631\u0643\u0628\u062a\u064a\u0643 \u062a\u062d\u062a \u0627\u0644\u0648\u0633\u0627\u062f\u0627\u062a.\n\u0623\u0645\u0633\u0643 \u0634\u0631\u064a\u0637 \u0627\u0644\u0643\u0627\u0628\u0644 \u0628\u0642\u0628\u0636\u0629 \u0639\u0644\u0648\u064a\u0629\u060c \u0628\u062d\u064a\u062b \u062a\u0643\u0648\u0646 \u0627\u0644\u0645\u0633\u0627\u0641\u0629 \u0628\u064a\u0646 \u0627\u0644\u0631\u062c\u0644\u064a\u0646 \u0623\u0648\u0633\u0639 \u0642\u0644\u064a\u0644\u0627\u064b \u0645\u0646 \u0639\u0631\u0636 \u0627\u0644\u0643\u062a\u0641\u064a\u0646.\n\u0627\u0646\u062d\u0646\u0650 \u0644\u0644\u062e\u0644\u0641 \u0642\u0644\u064a\u0644\u064b\u0627 \u0648\u062d\u0627\u0641\u0638 \u0639\u0644\u0649 \u0635\u062f\u0631\u0643 \u0645\u0631\u062a\u0641\u0639\u064b\u0627\u060c \u0645\u0639 \u0627\u0644\u062d\u0641\u0627\u0638 \u0639\u0644\u0649 \u0642\u0648\u0633 \u0637\u0641\u064a\u0641 \u0641\u064a \u0623\u0633\u0641\u0644 \u0638\u0647\u0631\u0643.\n\u0627\u0633\u062d\u0628 \u0627\u0644\u0628\u0627\u0631 \u0644\u0644\u0623\u0633\u0641\u0644 \u0646\u062d\u0648 \u0627\u0644\u062c\u0632\u0621 \u0627\u0644\u0639\u0644\u0648\u064a \u0645\u0646 \u0635\u062f\u0631\u0643\u060c \u0645\u0639 \u0627\u0644\u0636\u063a\u0637 \u0639\u0644\u0649 \u0644\u0648\u062d\u064a \u0627\u0644\u0643\u062a\u0641 \u0645\u0639\u064b\u0627.\n\u062a\u0648\u0642\u0641 \u0645\u0624\u0642\u062a\u064b\u0627 \u0644\u0644\u062d\u0638\u0629 \u0641\u064a \u0627\u0644\u062c\u0632\u0621 \u0627\u0644\u0633\u0641\u0644\u064a \u0645\u0646 \u0627\u0644\u062d\u0631\u0643\u0629\u060c \u062b\u0645 \u062d\u0631\u0631 \u0627\u0644\u0634\u0631\u064a\u0637 \u0628\u0628\u0637\u0621 \u0645\u0631\u0629 \u0623\u062e\u0631\u0649 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"2330","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"lats","secondary_muscles":["biceps","rhomboids","rear deltoids"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/2330-LEprlgG.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/2330-LEprlgG.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"31f32077-6f4c-5293-828b-ca396d8657e5","source_id":"0177","name_en":"cable lateral pulldown (with rope attachment)","name_ar":"\u0643\u0627\u0628\u0644 \u0645\u0646\u0633\u062f\u0644 \u062c\u0627\u0646\u0628\u064a (\u0645\u0639 \u062d\u0628\u0644 \u0645\u0631\u0641\u0642)","match_names":["cable lateral pulldown (with rope attachment)"],"muscle":"back","equipment":"cable","aliases":["cable lateral pulldown (with rope attachment)"],"logging_mode":"weighted_reps","load_convention":"external_total","guidance":{"steps_en":"Attach a rope attachment to the cable machine at a high position.\nStand facing the machine with your feet shoulder-width apart.\nGrasp the rope with an overhand grip, palms facing each other.\nKeep your back straight and lean slightly back.\nPull the rope down towards your sides, squeezing your shoulder blades together.\nPause for a moment at the bottom of the movement.\nSlowly release the tension and allow the rope to return to the starting position.\nRepeat for the desired number of repetitions.","steps_ar":"\u0642\u0645 \u0628\u062a\u0648\u0635\u064a\u0644 \u062d\u0628\u0644 \u0645\u0631\u0641\u0642 \u0628\u062c\u0647\u0627\u0632 \u0627\u0644\u0643\u0627\u0628\u0644 \u0641\u064a \u0645\u0648\u0636\u0639 \u0645\u0631\u062a\u0641\u0639.\n\u0642\u0641 \u0641\u064a \u0645\u0648\u0627\u062c\u0647\u0629 \u0627\u0644\u0622\u0644\u0629 \u0645\u0639 \u0645\u0628\u0627\u0639\u062f\u0629 \u0642\u062f\u0645\u064a\u0643 \u0628\u0645\u0642\u062f\u0627\u0631 \u0639\u0631\u0636 \u0627\u0644\u0643\u062a\u0641\u064a\u0646.\n\u0623\u0645\u0633\u0643 \u0627\u0644\u062d\u0628\u0644 \u0628\u0642\u0628\u0636\u0629 \u064a\u062f\u060c \u0645\u0639 \u0648\u0636\u0639 \u0631\u0627\u062d\u062a\u064a \u0627\u0644\u064a\u062f\u064a\u0646 \u0641\u064a \u0645\u0648\u0627\u062c\u0647\u0629 \u0628\u0639\u0636\u0647\u0645\u0627 \u0627\u0644\u0628\u0639\u0636.\n\u062d\u0627\u0641\u0638 \u0639\u0644\u0649 \u0627\u0633\u062a\u0642\u0627\u0645\u0629 \u0638\u0647\u0631\u0643 \u0648\u0627\u0631\u062c\u0639 \u0642\u0644\u064a\u0644\u0627\u064b \u0625\u0644\u0649 \u0627\u0644\u062e\u0644\u0641.\n\u0627\u0633\u062d\u0628 \u0627\u0644\u062d\u0628\u0644 \u0644\u0644\u0623\u0633\u0641\u0644 \u0628\u0627\u062a\u062c\u0627\u0647 \u062c\u0627\u0646\u0628\u064a\u0643\u060c \u0645\u0639 \u0627\u0644\u0636\u063a\u0637 \u0639\u0644\u0649 \u0644\u0648\u062d\u064a \u0643\u062a\u0641\u0643 \u0645\u0639\u064b\u0627.\n\u062a\u0648\u0642\u0641 \u0644\u0644\u062d\u0638\u0629 \u0641\u064a \u0623\u0633\u0641\u0644 \u0627\u0644\u062d\u0631\u0643\u0629.\n\u062d\u0631\u0631 \u0627\u0644\u062a\u0648\u062a\u0631 \u0628\u0628\u0637\u0621 \u0648\u0627\u0633\u0645\u062d \u0644\u0644\u062d\u0628\u0644 \u0628\u0627\u0644\u0639\u0648\u062f\u0629 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"0177","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"lats","secondary_muscles":["biceps","forearms"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/0177-CuaWCmC.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/0177-CuaWCmC.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"30ae24ca-5eff-556b-8923-283e278dcb34","source_id":"2616","name_en":"cable lateral pulldown with v-bar","name_ar":"\u0627\u0644\u0645\u0646\u0633\u062f\u0644\u0629 \u0627\u0644\u062c\u0627\u0646\u0628\u064a\u0629 \u0644\u0644\u0643\u0627\u0628\u0644 \u0645\u0639 \u0634\u0631\u064a\u0637 v","match_names":["cable lateral pulldown with v-bar"],"muscle":"back","equipment":"cable","aliases":["cable lateral pulldown with v-bar"],"logging_mode":"weighted_reps","load_convention":"external_total","guidance":{"steps_en":"Sit down on the cable pulldown machine and grab the v-bar attachment with an overhand grip.\nAdjust the knee pad so that your thighs are secured under it.\nKeep your back straight and lean back slightly.\nPull the v-bar down towards your upper chest while keeping your elbows close to your body.\nSqueeze your back muscles at the bottom of the movement.\nSlowly return the v-bar to the starting position and repeat for the desired number of repetitions.","steps_ar":"\u0627\u062c\u0644\u0633 \u0639\u0644\u0649 \u0622\u0644\u0629 \u0633\u062d\u0628 \u0627\u0644\u0643\u0627\u0628\u0644 \u0648\u0623\u0645\u0633\u0643 \u0628\u0645\u0644\u062d\u0642 v-bar \u0628\u0642\u0628\u0636\u0629 \u064a\u062f.\n\u0627\u0636\u0628\u0637 \u0648\u0633\u0627\u062f\u0629 \u0627\u0644\u0631\u0643\u0628\u0629 \u0628\u062d\u064a\u062b \u064a\u062a\u0645 \u062a\u062b\u0628\u064a\u062a \u0641\u062e\u0630\u064a\u0643 \u062a\u062d\u062a\u0647\u0627.\n\u062d\u0627\u0641\u0638 \u0639\u0644\u0649 \u0627\u0633\u062a\u0642\u0627\u0645\u0629 \u0638\u0647\u0631\u0643 \u0648\u0627\u0631\u062c\u0639 \u0644\u0644\u062e\u0644\u0641 \u0642\u0644\u064a\u0644\u064b\u0627.\n\u0627\u0633\u062d\u0628 \u0634\u0631\u064a\u0637 V \u0644\u0623\u0633\u0641\u0644 \u0628\u0627\u062a\u062c\u0627\u0647 \u0627\u0644\u062c\u0632\u0621 \u0627\u0644\u0639\u0644\u0648\u064a \u0645\u0646 \u0635\u062f\u0631\u0643 \u0645\u0639 \u0625\u0628\u0642\u0627\u0621 \u0645\u0631\u0641\u0642\u064a\u0643 \u0642\u0631\u064a\u0628\u064a\u0646 \u0645\u0646 \u062c\u0633\u0645\u0643.\n\u0627\u0636\u063a\u0637 \u0639\u0644\u0649 \u0639\u0636\u0644\u0627\u062a \u0638\u0647\u0631\u0643 \u0641\u064a \u0627\u0644\u062c\u0632\u0621 \u0627\u0644\u0633\u0641\u0644\u064a \u0645\u0646 \u0627\u0644\u062d\u0631\u0643\u0629.\n\u0642\u0645 \u0628\u0625\u0631\u062c\u0627\u0639 \u0634\u0631\u064a\u0637 v \u0628\u0628\u0637\u0621 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629 \u0648\u0643\u0631\u0631 \u0630\u0644\u0643 \u0644\u0639\u062f\u062f \u0627\u0644\u062a\u0643\u0631\u0627\u0631\u0627\u062a \u0627\u0644\u0645\u0637\u0644\u0648\u0628\u0629.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"2616","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"lats","secondary_muscles":["biceps","forearms"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/2616-4c9BhzB.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/2616-4c9BhzB.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"773519f2-0864-5bcc-8f5d-d6eef09bcf16","source_id":"0178","name_en":"cable lateral raise","name_ar":"\u0631\u0641\u0639 \u0627\u0644\u0643\u0627\u0628\u0644 \u0627\u0644\u062c\u0627\u0646\u0628\u064a","match_names":["cable lateral raise"],"muscle":"shoulders","equipment":"cable","aliases":["cable lateral raise"],"logging_mode":"weighted_reps","load_convention":"external_total","guidance":{"steps_en":"Stand with your feet shoulder-width apart and grasp the cable handles with an overhand grip.\nKeep your arms straight and your core engaged.\nRaise your arms out to the sides until they are parallel to the floor.\nPause for a moment at the top, then slowly lower your arms back down to the starting position.\nRepeat for the desired number of repetitions.","steps_ar":"\u0642\u0641 \u0645\u0639 \u0645\u0628\u0627\u0639\u062f\u0629 \u0642\u062f\u0645\u064a\u0643 \u0628\u0645\u0642\u062f\u0627\u0631 \u0639\u0631\u0636 \u0627\u0644\u0643\u062a\u0641\u064a\u0646 \u0648\u0623\u0645\u0633\u0643 \u0628\u0645\u0642\u0627\u0628\u0636 \u0627\u0644\u0643\u0627\u0628\u0644 \u0628\u0642\u0628\u0636\u0629 \u064a\u062f.\n\u062d\u0627\u0641\u0638 \u0639\u0644\u0649 \u0627\u0633\u062a\u0642\u0627\u0645\u0629 \u0630\u0631\u0627\u0639\u064a\u0643 \u0648\u062a\u0641\u0627\u0639\u0644 \u0642\u0644\u0628\u0643.\n\u0627\u0631\u0641\u0639 \u0630\u0631\u0627\u0639\u064a\u0643 \u0625\u0644\u0649 \u0627\u0644\u062c\u0627\u0646\u0628\u064a\u0646 \u062d\u062a\u0649 \u064a\u0635\u0628\u062d\u0627 \u0645\u0648\u0627\u0632\u064a\u064a\u0646 \u0644\u0644\u0623\u0631\u0636.\n\u062a\u0648\u0642\u0641 \u0644\u0644\u062d\u0638\u0629 \u0641\u064a \u0627\u0644\u0623\u0639\u0644\u0649\u060c \u062b\u0645 \u0623\u0646\u0632\u0644 \u0630\u0631\u0627\u0639\u064a\u0643 \u0628\u0628\u0637\u0621 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"0178","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"delts","secondary_muscles":["traps","triceps"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/0178-goJ6ezq.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/0178-goJ6ezq.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"fbbe0338-05f5-5749-87dc-585750452873","source_id":"0179","name_en":"cable low fly","name_ar":"\u0643\u0627\u0628\u0644 \u064a\u0637\u064a\u0631 \u0645\u0646\u062e\u0641\u0636","match_names":["cable low fly"],"muscle":"chest","equipment":"cable","aliases":["cable low fly"],"logging_mode":"weighted_reps","load_convention":"external_total","guidance":{"steps_en":"Attach the handles to the low pulleys of a cable machine and select an appropriate weight.\nStand in the middle of the machine with your feet shoulder-width apart and a slight bend in your knees.\nGrasp the handles with an overhand grip and extend your arms out to the sides, keeping a slight bend in your elbows.\nMaintaining control, slowly bring your arms forward in a sweeping motion, crossing them in front of your body.\nPause for a moment at the peak of the movement, feeling the stretch in your chest muscles.\nReverse the motion and slowly return your arms to the starting position, keeping tension on your chest muscles throughout.\nRepeat for the desired number of repetitions.","steps_ar":"\u0642\u0645 \u0628\u062a\u0648\u0635\u064a\u0644 \u0627\u0644\u0645\u0642\u0627\u0628\u0636 \u0628\u0627\u0644\u0628\u0643\u0631\u0627\u062a \u0627\u0644\u0645\u0646\u062e\u0641\u0636\u0629 \u0644\u0622\u0644\u0629 \u0627\u0644\u0643\u0627\u0628\u0644\u0627\u062a \u0648\u062d\u062f\u062f \u0627\u0644\u0648\u0632\u0646 \u0627\u0644\u0645\u0646\u0627\u0633\u0628.\n\u0642\u0641 \u0641\u064a \u0645\u0646\u062a\u0635\u0641 \u0627\u0644\u0622\u0644\u0629 \u0645\u0639 \u0645\u0628\u0627\u0639\u062f\u0629 \u0642\u062f\u0645\u064a\u0643 \u0628\u0645\u0642\u062f\u0627\u0631 \u0639\u0631\u0636 \u0627\u0644\u0643\u062a\u0641\u064a\u0646 \u0648\u062b\u0646\u064a \u0631\u0643\u0628\u062a\u064a\u0643 \u0642\u0644\u064a\u0644\u0627\u064b.\n\u0623\u0645\u0633\u0643 \u0627\u0644\u0645\u0642\u0627\u0628\u0636 \u0628\u0642\u0628\u0636\u0629 \u0639\u0644\u0648\u064a\u0629 \u0648\u0645\u062f \u0630\u0631\u0627\u0639\u064a\u0643 \u0625\u0644\u0649 \u0627\u0644\u062c\u0627\u0646\u0628\u064a\u0646\u060c \u0645\u0639 \u0627\u0644\u062d\u0641\u0627\u0638 \u0639\u0644\u0649 \u0627\u0646\u062d\u0646\u0627\u0621 \u0637\u0641\u064a\u0641 \u0641\u064a \u0645\u0631\u0641\u0642\u064a\u0643.\n\u0645\u0639 \u0627\u0644\u062d\u0641\u0627\u0638 \u0639\