machine with your feet shoulder-width apart and a slight bend in your knees.\nGrasp the bar with an overhand grip, keeping your arms straight and your palms facing down.\nEngage your core and keep your back straight as you exhale and push the bar down towards your thighs.\nPause for a moment at the bottom, then slowly return the bar to the starting position while inhaling.\nRepeat for the desired number of repetitions.","steps_ar":"\u0642\u0645 \u0628\u062a\u0648\u0635\u064a\u0644 \u0634\u0631\u064a\u0637 \u0645\u0633\u062a\u0642\u064a\u0645 \u0628\u0622\u0644\u0629 \u0643\u0627\u0628\u0644 \u0630\u0627\u062a \u0628\u0643\u0631\u0629 \u0639\u0627\u0644\u064a\u0629.\n\u0642\u0641 \u0641\u064a \u0645\u0648\u0627\u062c\u0647\u0629 \u0627\u0644\u0622\u0644\u0629 \u0645\u0639 \u0645\u0628\u0627\u0639\u062f\u0629 \u0642\u062f\u0645\u064a\u0643 \u0628\u0645\u0642\u062f\u0627\u0631 \u0639\u0631\u0636 \u0627\u0644\u0643\u062a\u0641\u064a\u0646 \u0648\u062b\u0646\u064a \u0631\u0643\u0628\u062a\u064a\u0643 \u0642\u0644\u064a\u0644\u0627\u064b.\n\u0623\u0645\u0633\u0643 \u0627\u0644\u0628\u0627\u0631 \u0628\u0642\u0628\u0636\u0629 \u0639\u0644\u0648\u064a\u0629\u060c \u0645\u0639 \u0625\u0628\u0642\u0627\u0621 \u0630\u0631\u0627\u0639\u064a\u0643 \u0645\u0633\u062a\u0642\u064a\u0645\u062a\u064a\u0646 \u0648\u0631\u0627\u062d\u062a\u064a \u064a\u062f\u064a\u0643 \u0645\u062a\u062c\u0647\u062a\u064a\u0646 \u0644\u0644\u0623\u0633\u0641\u0644.\n\u0642\u0645 \u0628\u0625\u0634\u0631\u0627\u0643 \u0642\u0644\u0628\u0643 \u0648\u062d\u0627\u0641\u0638 \u0639\u0644\u0649 \u0627\u0633\u062a\u0642\u0627\u0645\u0629 \u0638\u0647\u0631\u0643 \u0623\u062b\u0646\u0627\u0621 \u0627\u0644\u0632\u0641\u064a\u0631 \u0648\u0627\u062f\u0641\u0639 \u0627\u0644\u0634\u0631\u064a\u0637 \u0644\u0623\u0633\u0641\u0644 \u0628\u0627\u062a\u062c\u0627\u0647 \u0641\u062e\u0630\u064a\u0643.\n\u062a\u0648\u0642\u0641 \u0645\u0624\u0642\u062a\u064b\u0627 \u0644\u0644\u062d\u0638\u0629 \u0641\u064a \u0627\u0644\u0623\u0633\u0641\u0644\u060c \u062b\u0645 \u0623\u0639\u062f \u0627\u0644\u0634\u0631\u064a\u0637 \u0628\u0628\u0637\u0621 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629 \u0623\u062b\u0646\u0627\u0621 \u0627\u0644\u0627\u0633\u062a\u0646\u0634\u0627\u0642.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"0199","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"lats","secondary_muscles":["triceps","shoulders"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/0199-PskORrA.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/0199-PskORrA.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"b024a402-4ee5-55d0-857e-7cffe46d825c","source_id":"0200","name_en":"cable pushdown (with rope attachment)","name_ar":"\u0627\u0644\u0636\u063a\u0637 \u0639\u0644\u0649 \u0627\u0644\u0643\u0627\u0628\u0644 (\u0645\u0639 \u0645\u0631\u0641\u0642 \u0627\u0644\u062d\u0628\u0644)","match_names":["cable pushdown (with rope attachment)"],"muscle":"triceps","equipment":"cable","aliases":["cable pushdown (with rope attachment)"],"logging_mode":"weighted_reps","load_convention":"external_total","guidance":{"steps_en":"Attach a rope attachment to a high pulley on a cable machine.\nStand facing the machine with your feet shoulder-width apart and a slight bend in your knees.\nGrasp the rope with an overhand grip, palms facing each other.\nKeep your elbows close to your sides and your upper arms stationary throughout the exercise.\nExhale and push the rope downward by extending your elbows until your arms are fully extended.\nPause for a moment, then inhale and slowly return to the starting position by allowing your elbows to flex.\nRepeat for the desired number of repetitions.","steps_ar":"\u0642\u0645 \u0628\u062a\u0648\u0635\u064a\u0644 \u062d\u0628\u0644 \u0645\u0631\u0641\u0642 \u0628\u0628\u0643\u0631\u0629 \u0639\u0627\u0644\u064a\u0629 \u0639\u0644\u0649 \u062c\u0647\u0627\u0632 \u0627\u0644\u0643\u0627\u0628\u0644.\n\u0642\u0641 \u0641\u064a \u0645\u0648\u0627\u062c\u0647\u0629 \u0627\u0644\u0622\u0644\u0629 \u0645\u0639 \u0645\u0628\u0627\u0639\u062f\u0629 \u0642\u062f\u0645\u064a\u0643 \u0628\u0645\u0642\u062f\u0627\u0631 \u0639\u0631\u0636 \u0627\u0644\u0643\u062a\u0641\u064a\u0646 \u0648\u062b\u0646\u064a \u0631\u0643\u0628\u062a\u064a\u0643 \u0642\u0644\u064a\u0644\u0627\u064b.\n\u0623\u0645\u0633\u0643 \u0627\u0644\u062d\u0628\u0644 \u0628\u0642\u0628\u0636\u0629 \u064a\u062f\u060c \u0645\u0639 \u0648\u0636\u0639 \u0631\u0627\u062d\u062a\u064a \u0627\u0644\u064a\u062f\u064a\u0646 \u0641\u064a \u0645\u0648\u0627\u062c\u0647\u0629 \u0628\u0639\u0636\u0647\u0645\u0627 \u0627\u0644\u0628\u0639\u0636.\n\u0623\u0628\u0642\u0650 \u0645\u0631\u0641\u0642\u064a\u0643 \u0642\u0631\u064a\u0628\u064a\u0646 \u0645\u0646 \u062c\u0627\u0646\u0628\u064a\u0643 \u0648\u0630\u0631\u0627\u0639\u064a\u0643 \u0627\u0644\u0639\u0644\u0648\u064a\u064a\u0646 \u062b\u0627\u0628\u062a\u064a\u0646 \u0637\u0648\u0627\u0644 \u0627\u0644\u062a\u0645\u0631\u064a\u0646.\n\u0642\u0645 \u0628\u0627\u0644\u0632\u0641\u064a\u0631 \u0648\u0627\u062f\u0641\u0639 \u0627\u0644\u062d\u0628\u0644 \u0625\u0644\u0649 \u0627\u0644\u0623\u0633\u0641\u0644 \u0639\u0646 \u0637\u0631\u064a\u0642 \u062a\u0645\u062f\u064a\u062f \u0645\u0631\u0641\u0642\u064a\u0643 \u062d\u062a\u0649 \u064a\u062a\u0645 \u062a\u0645\u062f\u064a\u062f \u0630\u0631\u0627\u0639\u064a\u0643 \u0628\u0627\u0644\u0643\u0627\u0645\u0644.\n\u062a\u0648\u0642\u0641 \u0644\u0644\u062d\u0638\u0629\u060c \u062b\u0645 \u062e\u0630 \u0634\u0647\u064a\u0642\u064b\u0627 \u062b\u0645 \u0639\u062f \u0628\u0628\u0637\u0621 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629 \u0645\u0646 \u062e\u0644\u0627\u0644 \u0627\u0644\u0633\u0645\u0627\u062d \u0644\u0645\u0631\u0641\u0642\u064a\u0643 \u0628\u0627\u0644\u062b\u0646\u064a.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"0200","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"triceps","secondary_muscles":["forearms"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/0200-dU605di.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/0200-dU605di.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"1d718e70-fd52-50c1-8215-c80aa64be70f","source_id":"0202","name_en":"cable rear delt row (stirrups)","name_ar":"\u0635\u0641 \u062f\u0644\u062a \u0627\u0644\u062e\u0644\u0641\u064a \u0644\u0644\u0643\u0627\u0628\u0644 (\u0627\u0644\u0631\u0643\u0627\u0628)","match_names":["cable rear delt row (stirrups)"],"muscle":"shoulders","equipment":"cable","aliases":["cable rear delt row (stirrups)"],"logging_mode":"weighted_reps","load_convention":"external_total","guidance":{"steps_en":"Attach a stirrup handle to a low cable pulley and stand facing the machine.\nGrasp the handle with your left hand and take a step back with your right foot, positioning your body at a slight angle.\nBend your knees slightly and hinge forward at the hips, keeping your back straight and your core engaged.\nWith your left arm extended and your palm facing down, pull the handle towards your chest by retracting your shoulder blade.\nPause for a moment at the top of the movement, squeezing your shoulder blade.\nSlowly release the handle back to the starting position and repeat for the desired number of repetitions.\nSwitch sides and repeat the exercise with your right arm.","steps_ar":"\u0642\u0645 \u0628\u062a\u0648\u0635\u064a\u0644 \u0645\u0642\u0628\u0636 \u0627\u0644\u0631\u0650\u0651\u0643\u0627\u0628 \u0628\u0628\u0643\u0631\u0629 \u0643\u0627\u0628\u0644 \u0645\u0646\u062e\u0641\u0636\u0629 \u0648\u0627\u0644\u0648\u0642\u0648\u0641 \u0641\u064a \u0645\u0648\u0627\u062c\u0647\u0629 \u0627\u0644\u0645\u0627\u0643\u064a\u0646\u0629.\n\u0623\u0645\u0633\u0643 \u0627\u0644\u0645\u0642\u0628\u0636 \u0628\u064a\u062f\u0643 \u0627\u0644\u064a\u0633\u0631\u0649 \u0648\u062a\u0631\u0627\u062c\u0639 \u0628\u0642\u062f\u0645\u0643 \u0627\u0644\u064a\u0645\u0646\u0649\u060c \u0645\u0639 \u0648\u0636\u0639 \u062c\u0633\u0645\u0643 \u0641\u064a \u0632\u0627\u0648\u064a\u0629 \u0637\u0641\u064a\u0641\u0629.\n\u0627\u062b\u0646\u0650 \u0631\u0643\u0628\u062a\u064a\u0643 \u0642\u0644\u064a\u0644\u064b\u0627 \u0648\u062b\u0628\u062a\u0647\u0645\u0627 \u0644\u0644\u0623\u0645\u0627\u0645 \u0639\u0646\u062f \u0627\u0644\u0648\u0631\u0643\u064a\u0646\u060c \u0645\u0639 \u0627\u0644\u062d\u0641\u0627\u0638 \u0639\u0644\u0649 \u0627\u0633\u062a\u0642\u0627\u0645\u0629 \u0638\u0647\u0631\u0643 \u0648\u062c\u0630\u0628 \u062c\u0630\u0639\u0643.\n\u0645\u0639 \u062a\u0645\u062f\u064a\u062f \u0630\u0631\u0627\u0639\u0643 \u0627\u0644\u064a\u0633\u0631\u0649 \u0648\u0631\u0627\u062d\u0629 \u064a\u062f\u0643 \u0644\u0623\u0633\u0641\u0644\u060c \u0627\u0633\u062d\u0628 \u0627\u0644\u0645\u0642\u0628\u0636 \u0646\u062d\u0648 \u0635\u062f\u0631\u0643 \u0639\u0646 \u0637\u0631\u064a\u0642 \u0633\u062d\u0628 \u0644\u0648\u062d \u0643\u062a\u0641\u0643.\n\u062a\u0648\u0642\u0641 \u0644\u0644\u062d\u0638\u0629 \u0641\u064a \u0627\u0644\u062c\u0632\u0621 \u0627\u0644\u0639\u0644\u0648\u064a \u0645\u0646 \u0627\u0644\u062d\u0631\u0643\u0629\u060c \u0645\u0639 \u0627\u0644\u0636\u063a\u0637 \u0639\u0644\u0649 \u0644\u0648\u062d \u0643\u062a\u0641\u0643.\n\u062d\u0631\u0631 \u0627\u0644\u0645\u0642\u0628\u0636 \u0628\u0628\u0637\u0621 \u0645\u0631\u0629 \u0623\u062e\u0631\u0649 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629 \u0648\u0643\u0631\u0631 \u0630\u0644\u0643 \u0644\u0639\u062f\u062f \u0627\u0644\u062a\u0643\u0631\u0627\u0631 \u0627\u0644\u0645\u0637\u0644\u0648\u0628.\n\u0642\u0645 \u0628\u062a\u0628\u062f\u064a\u0644 \u0627\u0644\u062c\u0648\u0627\u0646\u0628 \u0648\u0643\u0631\u0631 \u0627\u0644\u062a\u0645\u0631\u064a\u0646 \u0628\u0630\u0631\u0627\u0639\u0643 \u0627\u0644\u064a\u0645\u0646\u0649.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"0202","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"delts","secondary_muscles":["trapezius","rhomboids","biceps"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/0202-yUdIGNs.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/0202-yUdIGNs.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"231417da-a988-5f52-8d18-7267dcaff1f1","source_id":"0203","name_en":"cable rear delt row (with rope)","name_ar":"\u0635\u0641 \u062f\u0644\u062a \u062e\u0644\u0641\u064a \u0644\u0644\u0643\u0627\u0628\u0644 (\u0645\u0639 \u062d\u0628\u0644)","match_names":["cable rear delt row (with rope)"],"muscle":"shoulders","equipment":"cable","aliases":["cable rear delt row (with rope)"],"logging_mode":"weighted_reps","load_convention":"external_total","guidance":{"steps_en":"Attach a rope handle to a low pulley cable machine.\nStand facing the machine with your feet shoulder-width apart.\nGrasp the rope handle with an overhand grip, palms facing each other.\nBend your knees slightly and hinge forward at the hips, keeping your back straight.\nKeep your elbows slightly bent and pull the rope towards your chest, squeezing your shoulder blades together.\nPause for a moment at the top of the movement, then slowly release the tension and return to the starting position.\nRepeat for the desired number of repetitions.","steps_ar":"\u0642\u0645 \u0628\u062a\u0648\u0635\u064a\u0644 \u0645\u0642\u0628\u0636 \u062d\u0628\u0644 \u0628\u0622\u0644\u0629 \u0643\u0627\u0628\u0644 \u0630\u0627\u062a \u0628\u0643\u0631\u0629 \u0645\u0646\u062e\u0641\u0636\u0629.\n\u0642\u0641 \u0641\u064a \u0645\u0648\u0627\u062c\u0647\u0629 \u0627\u0644\u0622\u0644\u0629 \u0645\u0639 \u0645\u0628\u0627\u0639\u062f\u0629 \u0642\u062f\u0645\u064a\u0643 \u0628\u0645\u0642\u062f\u0627\u0631 \u0639\u0631\u0636 \u0627\u0644\u0643\u062a\u0641\u064a\u0646.\n\u0623\u0645\u0633\u0643 \u0628\u0645\u0642\u0628\u0636 \u0627\u0644\u062d\u0628\u0644 \u0628\u0642\u0628\u0636\u0629 \u064a\u062f\u060c \u0628\u062d\u064a\u062b \u062a\u0648\u0627\u062c\u0647 \u0631\u0627\u062d\u062a\u0627 \u0627\u0644\u064a\u062f\u064a\u0646 \u0628\u0639\u0636\u0647\u0645\u0627 \u0627\u0644\u0628\u0639\u0636.\n\u0627\u062b\u0646\u0650 \u0631\u0643\u0628\u062a\u064a\u0643 \u0642\u0644\u064a\u0644\u064b\u0627 \u0648\u062b\u0628\u062a\u0647\u0645\u0627 \u0644\u0644\u0623\u0645\u0627\u0645 \u0639\u0646\u062f \u0627\u0644\u0648\u0631\u0643\u064a\u0646\u060c \u0645\u0639 \u0627\u0644\u062d\u0641\u0627\u0638 \u0639\u0644\u0649 \u0627\u0633\u062a\u0642\u0627\u0645\u0629 \u0638\u0647\u0631\u0643.\n\u0623\u0628\u0642\u0650 \u0645\u0631\u0641\u0642\u064a\u0643 \u0645\u062b\u0646\u064a\u064a\u0646 \u0642\u0644\u064a\u0644\u0627\u064b \u0648\u0627\u0633\u062d\u0628 \u0627\u0644\u062d\u0628\u0644 \u0646\u062d\u0648 \u0635\u062f\u0631\u0643\u060c \u0645\u0639 \u0627\u0644\u0636\u063a\u0637 \u0639\u0644\u0649 \u0644\u0648\u062d\u064a \u0643\u062a\u0641\u064a\u0643 \u0645\u0639\u064b\u0627.\n\u062a\u0648\u0642\u0641 \u0645\u0624\u0642\u062a\u064b\u0627 \u0644\u0644\u062d\u0638\u0629 \u0641\u064a \u0627\u0644\u062c\u0632\u0621 \u0627\u0644\u0639\u0644\u0648\u064a \u0645\u0646 \u0627\u0644\u062d\u0631\u0643\u0629\u060c \u062b\u0645 \u062d\u0631\u0631 \u0627\u0644\u062a\u0648\u062a\u0631 \u0628\u0628\u0637\u0621 \u0648\u0627\u0631\u062c\u0639 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"0203","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"delts","secondary_muscles":["trapezius","rhomboids","biceps"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4